import { useEffect, useState } from 'react';

export function Cart({ items, userId }: { items: { price: number; qty: number }[]; userId: string }) {
  const [total, setTotal] = useState(0);
  const [note, setNote] = useState('');
  useEffect(() => { setTotal(items.reduce((s, i) => s + i.price * i.qty, 0)); }, [items]);
  useEffect(() => { setNote(''); }, [userId]);
  return <form><input value={note} onChange={e => setNote(e.target.value)} /><p>{total}</p></form>;
}

