import { useEffect } from 'react';
import { connect, notify } from './chat';

export function ChatRoom({ roomId, theme }: { roomId: string; theme: 'light' | 'dark' }) {
  useEffect(() => {
    const c = connect(roomId);
    c.on('connected', () => notify('Połączono', theme));
    return () => c.disconnect();
  }, [roomId, theme]);
  return null;
}
